hepcatDirectory = ParentDirectory[Global`$HEPCATpath];
modelDirectory = FileNameJoin[{hepcatDirectory, "models"}];
qedModel = ReadModel[modelDirectory, 2];
Length /@ qedModel

diagrams = CreateDiagrams[process, qedModel];
rawAmplitudes = diagramAmplitudes[diagrams];
CreateArrowDiagrams[diagrams]

highEnergy = CompleteHighEnergy[factorized, channels, qedModel, "Output" -> "Details"];
finalAmplitude = {highEnergy["ExternalMassRules"], highEnergy["Amplitude"]};
finalAmplitude = PrepareAmplitudes[finalAmplitude, qedModel];

knownModel = ReadModel[modelDirectory, 3];
processes = {{"e", "E", "A.+", "A.+"}, {"e", "E", "A.+", "A.-"}, {"e", "E", "A.-", "A.-"}};
entries = {#, LookupAmplitude[Thread[{#, Range[4]}], knownModel, False, {i1, i2, i3, i4}]} & /@ processes;
